package br.com.dmp.widget
import android.app.Activity
import android.appwidget.AppWidgetManager
import android.os.Bundle
import android.content.Intent
import android.widget.*
class WidgetSettingsActivity:Activity(){override fun onCreate(b:Bundle?){super.onCreate(b);val id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);if(id==AppWidgetManager.INVALID_APPWIDGET_ID){finish();return};val p=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(28,48,28,28)};p.addView(TextView(this).apply{text="Configurar widget DMP";textSize=24f});val label=TextView(this);p.addView(label);val opacity=SeekBar(this).apply{max=80;progress=WidgetSettings.value(this@WidgetSettingsActivity,id,"opacity",90)-20};fun label(){label.text="Opacidade do fundo: ${opacity.progress+20}%"};label();opacity.setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,v:Int,u:Boolean){label()};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){} });p.addView(opacity);p.addView(TextView(this).apply{text="A Agenda mostra hoje e amanhã com rolagem interna. Redimensione o widget para ver mais horários ao mesmo tempo."});fun toggle(label:String,key:String,default:Boolean)=CheckBox(this).apply{text=label;isChecked=WidgetSettings.flag(this@WidgetSettingsActivity,id,key,default);p.addView(this)}
 val tomorrow=toggle("Agenda: mostrar hoje + amanhã","tomorrow",true);val calendar=toggle("Hoje: mini calendário quando houver espaço","calendar",true);val notes=toggle("Hoje: mostrar compromissos","notes",true);p.addView(Button(this).apply{text="Salvar este widget";setOnClickListener{WidgetSettings.save(this@WidgetSettingsActivity,id,opacity.progress+20,WidgetSettings.value(this@WidgetSettingsActivity,id,"items",8),tomorrow.isChecked,calendar.isChecked,notes.isChecked);TodayWidget.renderAll(this@WidgetSettingsActivity);TodayWidget.schedule(this@WidgetSettingsActivity);setResult(RESULT_OK,Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish()}});p.addView(Button(this).apply{text="Conectar / gerenciar DMP";setOnClickListener{startActivity(Intent(this@WidgetSettingsActivity,ConfigureActivity::class.java))}});setContentView(ScrollView(this).apply{addView(p);setOnApplyWindowInsetsListener{v,i->v.setPadding(0,i.systemWindowInsetTop,0,i.systemWindowInsetBottom);i}})}}
